import React, { useState, useRef, useEffect } from 'react';
import { CLS } from './classes.js';

const Square = (props) => {
  const sq = new CLS(props.className).add('square');
  const [ height, setHeight ] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const resize = () => setHeight(ref.current.clientWidth);
    window.addEventListener("resize", resize);
    resize();
    return () => window.removeEventListener('resize', resize);
  }, []);
  return (
    <div className="square-container">
      <div {...props} ref={ref} className={sq.prt()} style={{ height }}>
        {props.children}
      </div>
    </div>
  )
}

const Loading = (props) => {
  const style = {
    width: '100%',
    height: '100%'
  }
  let ready = true;
  for (let i of props.require) {
    if (!i) ready = false;
  }

  return ready ? props.children :  (
    <Square className="spinner-grow" style={style} role="status">
      <span className="visually-hidden">Loading...</span>
    </Square>
  );
}

class cls extends Array {
  constructor(...args) {
    super(...args);
  }
  
  add(string) {
    if (!this.includes(string)) {
      this.push(string);
    }
    return this;
  }

  remove(string) {
    if (this.includes(string)) {
      this.length = 0;
      this.push(...this.filter(i => i !== string));
    }
    return this;
  }
}

export { Square, Loading };